/**
 * Real AFL draft & trade history, sourced from draftguru.com.au's per-year pages (fetched Aug
 * 2026). See `../../Real Draft History and Prospect Talent Pool.md` (vault root) for the full
 * design note, the data-model research, and Tyler's own steer on the three open forks (Aug 2026,
 * round 65): full 18-year capture (this file — COMPLETE, see below), extend the existing
 * real-player system (this file is consumed the same way `realWorldRecords.ts` is — see
 * `engine/records.ts`'s `getPlayerByFullName` merge pattern), and — separately, NOT built here —
 * feed the real 2026/2027 prospect pool into `engine/draft.ts`'s procedural generator.
 *
 * Games/Goals/CoachesVotes/BrownlowVotes are presented by draftguru as career-to-date cumulative
 * totals, but this is NOT reliably true across the site: the same player appears with materially
 * different "cumulative" figures on different year pages (e.g. Jack Gunston shows 286 games on his
 * 2011 row, 75 on his 2022 row, and 58 on his 2023 row; Jeremy Cameron shows 297 games on his 2010
 * row but 125 on his 2020 row) — i.e. these are scrape-timing snapshots specific to when draftguru
 * last touched that year's page, not a single consistent running total. Treat every row's stat
 * line as "as recorded on that row," not as directly comparable across a player's multiple rows.
 * Grade is draftguru's own retrospective "how'd this pick turn out" value call (A+ down to D), not
 * anything AussieFootySim computes.
 *
 * COVERAGE, HONESTLY: all 18 years (2008-2025) are captured in full — every row on each year's
 * draftguru.com.au page, hand-transcribed and reconciled against that page's own reported
 * type/total counts (~2,700 rows total). A handful of players who appear on more than one year's
 * page (traded, delisted and re-rookied, etc.) will have more than one row in
 * `REAL_DRAFT_HISTORY` — `draftHistoryFor` returns all of them, not just one. ageAtEntry/heightCm
 * are `null` on the rare row where draftguru itself has no recorded value, rather than guessed.
 */

export interface DraftHistoryEntry {
  year: number;
  draftType:
    | "FA"
    | "Trade"
    | "Pre-Draft"
    | "National"
    | "Pre-Season"
    | "Rookie"
    | "Post-Draft"
    | "Mid-Season"
    | "Mini-Draft"
    | "Training Squad Selection";
  /** Pick number within that draftType for that year, where draftguru records one (null for FA/Trade/most Post-Draft rows, which aren't numbered picks). */
  pickNumber: number | null;
  club: string;
  /** "First Last", matched against `loadPlayers.ts`'s `playerFullName`/`getPlayerByFullName` for a currently-loaded real+sim player. */
  player: string;
  /** null for the rare row where draftguru itself has no recorded age (e.g. Amua Parika, 2009 Pre-Draft). */
  ageAtEntry: number | null;
  /** null for the rare row where draftguru itself has no recorded height (e.g. a code convert pre-measurement). */
  heightCm: number | null;
  /** draftguru's own A+ (best) to D (worst) retrospective value grade for this pick/signing. */
  grade: string;
  /** Career-to-date games, as of the Aug 2026 scrape. */
  games: number;
  goals: number;
  coachesVotes: number;
  brownlowVotes: number;
  /** Raw semicolon-separated honours text, e.g. "AA: 2023, 2024; B&F: 2024" — empty string if none. */
  awards: string;
}

// Compact tuple form to keep ~140 rows/year readable; mapped to DraftHistoryEntry below.
type RawRow = [
  number,
  DraftHistoryEntry["draftType"],
  number | null,
  string,
  string,
  number | null,
  number | null,
  string,
  number,
  number,
  number,
  number,
  string,
];

function toEntry(r: RawRow): DraftHistoryEntry {
  return {
    year: r[0],
    draftType: r[1],
    pickNumber: r[2],
    club: r[3],
    player: r[4],
    ageAtEntry: r[5],
    heightCm: r[6],
    grade: r[7],
    games: r[8],
    goals: r[9],
    coachesVotes: r[10],
    brownlowVotes: r[11],
    awards: r[12],
  };
}

